                fail(`ERR wrong number of arguments for '${verb.toLowerCase()}' command`);
            }
            return this[group](verb, args);
    strings(verb, args) {
        const key = args[0];
        switch (verb) {
        case 'SET': {
            const options = new Map();
            for (let index = 2; index < args.length; ++index) {
